import React, { useState } from 'react';
import Header from '../components/header/header';
import Footer from '../components/footer/footer';
import { FaPhoneAlt, FaEnvelope, FaMapMarkerAlt, FaClock, FaCheckCircle, FaStar, FaGoogle, FaShieldAlt, FaTools, FaPhone, FaArrowRight } from 'react-icons/fa';
import '../styles/contact-page.css';
import { BUSINESS, CONTACT_PAGE, SERVICES } from '../content';
import heroBg from '../images/hero.jpg';

const ContactPage: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    service: SERVICES[0]?.title || 'General Inquiry',
    message: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    alert('Thank you for your message! Our team will get back to you shortly.');
  };

  return (
    <div className="contact-page">
      <Header />

      {/* Hero Section */}
      <section className="contact-hero">
        <div className="contact-hero-bg">
          <img src={heroBg} alt={BUSINESS.name} />
        </div>
        <div className="contact-hero-overlay"></div>
        <div className="contact-hero-content container">
          <div className="badge">{CONTACT_PAGE.badge}</div>
          <h1 className="hero-title">{CONTACT_PAGE.heroTitle} <span className="highlight">{CONTACT_PAGE.heroTitleHighlight}</span></h1>
          <p className="hero-description">
            {CONTACT_PAGE.heroDesc}
          </p>
        </div>
      </section>

      {/* Main Content Section */}
      <section className="contact-main">
        <div className="container">
          <div className="contact-grid">
            {/* Info Side */}
            <div className="contact-info-side">
              <h2>{CONTACT_PAGE.infoTitle}</h2>
              <p>{CONTACT_PAGE.infoDesc}</p>

              <div className="contact-details-list">
                <div className="contact-item">
                  <div className="contact-icon">
                    <FaPhoneAlt />
                  </div>
                  <div className="contact-text">
                    <h3>Call Us Directly</h3>
                    <a href={BUSINESS.phoneHref}>{BUSINESS.phone}</a>
                  </div>
                </div>

                <div className="contact-item">
                  <div className="contact-icon">
                    <FaEnvelope />
                  </div>
                  <div className="contact-text">
                    <h3>Email Support</h3>
                    <a href={BUSINESS.emailHref}>{BUSINESS.email}</a>
                  </div>
                </div>

                <div className="contact-item">
                  <div className="contact-icon">
                    <FaMapMarkerAlt />
                  </div>
                  <div className="contact-text">
                    <h3>Our Service Area</h3>
                    <p>{BUSINESS.serviceArea}</p>
                  </div>
                </div>

                <div className="contact-item">
                  <div className="contact-icon">
                    <FaClock />
                  </div>
                  <div className="contact-text">
                    <h3>Business Hours</h3>
                    <p dangerouslySetInnerHTML={{ __html: BUSINESS.hours }}></p>
                  </div>
                </div>
              </div>
            </div>

            {/* Form Side */}
            <div className="contact-form-side">
              <form onSubmit={handleSubmit}>
                <div className="form-group">
                  <label htmlFor="name">Full Name</label>
                  <input 
                    type="text" 
                    id="name" 
                    name="name" 
                    placeholder="Enter your name" 
                    value={formData.name}
                    onChange={handleChange}
                    required 
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="email">Email Address</label>
                  <input 
                    type="email" 
                    id="email" 
                    name="email" 
                    placeholder="name@email.com" 
                    value={formData.email}
                    onChange={handleChange}
                    required 
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="phone">Phone Number</label>
                  <input 
                    type="tel" 
                    id="phone" 
                    name="phone" 
                    placeholder="(000) 000-0000" 
                    value={formData.phone}
                    onChange={handleChange}
                    required 
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="service">Desired Service</label>
                  <select 
                    id="service" 
                    name="service" 
                    value={formData.service}
                    onChange={handleChange}
                  >
                    {SERVICES.map((service) => (
                      <option key={service.id} value={service.title}>{service.title}</option>
                    ))}
                    <option value="Custom Project">Custom Project</option>
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="message">How can we help?</label>
                  <textarea 
                    id="message" 
                    name="message" 
                    rows={4} 
                    placeholder="Tell us about your project..." 
                    value={formData.message}
                    onChange={handleChange}
                    required 
                  ></textarea>
                </div>

                <button type="submit" className="submit-btn" disabled={!formData.name || !formData.email}>
                  Send Message <FaArrowRight />
                </button>
              </form>
            </div>
          </div>
        </div>
      </section>

      {/* Map Section */}
      <section className="map-section">
        <iframe 
          src={BUSINESS.googleMapsEmbed} 
          width="100%" 
          height="500" 
          style={{ border: 0 }} 
          allowFullScreen={true}
          loading="lazy" 
          referrerPolicy="no-referrer-when-downgrade"
          title={`${BUSINESS.name} Office Location`}
        ></iframe>
      </section>

      <Footer />
    </div>
  );
};

export default ContactPage;

